    private static T Load<T>(string fileName)
    {
        string path = Path.Combine(AppContext.BaseDirectory, "GoldenVectors", fileName);
        T? value = JsonSerializer.Deserialize<T>(File.ReadAllText(path));
        return value ?? throw new InvalidDataException($"{fileName} is empty.");
    }

